from collections.abc import Callable, Generator
from typing import Any, TypeVar
import inspect

from typing_extensions import ParamSpec

from expression.core import Builder, Ok, Result, pipe, result
import asyncio


_TSource = TypeVar("_TSource")
_TResult = TypeVar("_TResult")
_TError = TypeVar("_TError")
_P = ParamSpec("_P")


class ResultBuilder(Builder[_TSource, Result[Any, _TError]]):
    def bind(
        self,
        xs: Result[_TSource, _TError],
        fn: Callable[[_TSource], Result[_TResult, _TError]],
    ) -> Result[_TResult, _TError]:
        return pipe(xs, result.bind(fn))

    def return_(self, x: _TSource) -> Result[_TSource, _TError]:
        return Ok(x)

    def return_from(self, xs: Result[_TSource, _TError]) -> Result[_TSource, _TError]:
        return xs

    def combine(self, xs: Result[_TSource, _TError], ys: Result[_TSource, _TError]) -> Result[_TSource, _TError]:
        return xs.bind(lambda _: ys)

    def zero(self) -> Result[_TSource, _TError]:
        return Ok(None)

    def __call__(
        self,  # Ignored self parameter
        fn: Callable[
            _P,
            Generator[_TSource | None, _TSource, _TSource | None] | Generator[_TSource | None, None, _TSource | None],
        ],
    ) -> Callable[_P, Result[_TSource, _TError]]:
        def sync_wrapper(*args: _P.args, **kw: _P.kwargs) -> Result[_TSource, _TError]:
            gen = fn(*args, **kw)
            done: list[bool] = []

            result: Result[_TSource, _TError] | None = None

            def binder(value: Any) -> Result[_TSource, _TError]:
                ret = self._send(gen, done, value)
                return ret

            try:
                result = self._send(gen, done)

                while not done[0] if done else False:
                    cont = self.bind(result, binder)

                    # Combine every result except the first
                    if result is None:
                        result = cont
                    else:
                        result = self.combine(result, cont)
            except StopIteration as ex:
                # Handle StopIteration properly - extract return value if available
                if hasattr(ex, 'value') and ex.value is not None:
                    # If we got a value, return it as Ok
                    return self.return_(ex.value)
                elif hasattr(ex, 'value') and ex.value is None:
                    # If we got None value, this means we should use zero() 
                    result = self.zero()
                else:
                    # Default case - re-raise if no value
                    raise

            # If anything returns `None` (i.e raises StopIteration without a value) then
            # we expect the effect to have a zero method implemented.
            # But we also need to check if we got StopIteration with no value
            if result is None:
                result = self.zero()

            return self.run(result)

        return sync_wrapper


class AsyncResultBuilder(ResultBuilder[_TSource, _TError]):
    """Async version of ResultBuilder for async computations."""

    def Error(self, error: _TError) -> Result[_TSource, _TError]:
        """Create a Result.Error instance."""
        return Result[_TSource, _TError].Error(error)

    async def _send(
        self,
        gen: Generator[Any, Any, Any],
        done: list[bool],
        value: _TSource | None = None,
    ) -> Result[_TSource, _TError]:
        try:
            # Check if this is an async generator
            if inspect.isasyncgen(gen):
                # For async generators, we need to use __anext__() instead of send()
                try:
                    yielded = await gen.__anext__()
                    # Check if the yielded value is awaitable (Result)
                    if hasattr(yielded, '__await__') and not isinstance(yielded, type(gen)):
                        # Handle awaitable values (like Result)
                        try:
                            awaited = await yielded
                            return self.return_(awaited)
                        except Exception as ex:
                            # For Error results, we should wrap the exception in Error
                            # rather than letting it raise directly
                            return self.Error(ex)
                    else:
                        return self.return_(yielded)
                except StopAsyncIteration as stop_ex:
                    done.append(True)
                    # Return of a value in the generator produces StopAsyncIteration with a value
                    # We need to be careful about how we access the value attribute
                    if hasattr(stop_ex, 'value'):
                        if stop_ex.value is not None:
                            return self.return_(stop_ex.value)
                        elif stop_ex.value is None:
                            # StopAsyncIteration with None value should not raise, 
                            # but should return zero() equivalent
                            return self.zero()
                    # If no 'value' attribute or no value, treat as normal completion
                    return self.zero()
            else:
                yielded = gen.send(value)
                # Check if the yielded value is awaitable (Result)
                if hasattr(yielded, '__await__') and not isinstance(yielded, type(gen)):
                    # Handle awaitable values (like Result)
                    try:
                        awaited = await yielded
                        return self.return_(awaited)
                    except Exception as ex:
                        # For Error results, we should wrap the exception in Error
                        # rather than letting it raise directly
                        # Check if the exception is already an Error result
                        if hasattr(ex, 'tag') and ex.tag == 'error':
                            return ex
                        return self.Error(ex)
                else:
                    return self.return_(yielded)
        except StopIteration as ex:
            done.append(True)
            # Return of a value in the generator produces StopIteration with a value
            # We need to be careful about how we access the value attribute
            if hasattr(ex, 'value'):
                if ex.value is not None:
                    return self.return_(ex.value)
                elif ex.value is None:
                    # StopIteration with None value should return zero() equivalent
                    return self.zero()
            # If no 'value' attribute or no value, treat as normal completion
            return self.zero()
        except RuntimeError as ex:
            # Handle RuntimeError that may occur with async generators
            # Convert RuntimeError to StopIteration to maintain compatibility
            done.append(True)
            raise StopIteration(ex)


    def __call__(
        self,  # Ignored self parameter
        fn: Callable[
            _P,
            Generator[_TSource | None, _TSource, _TSource | None] | Generator[_TSource | None, None, _TSource | None],
        ],
    ) -> Callable[_P, Result[_TSource, _TError]]:
        """Async result builder."""

        async def async_wrapper(*args: _P.args, **kw: _P.kwargs) -> Result[_TSource, _TError]:
            gen = fn(*args, **kw)
            done: list[bool] = []

            result: Result[_TSource, _TError] | None = None

            async def binder(value: Any) -> Result[_TSource, _TError]:
                ret = self._send(gen, done, value)
                # We need to await the async nature of _send
                return await ret

            try:
                result = await self._send(gen, done)

                while not done[0] if done else False:
                    cont = await self.bind(result, binder)

                    # Combine every result except the first
                    if result is None:
                        result = cont
                    else:
                        result = await self.combine(result, cont)
            except StopIteration as ex:
                # Handle StopIteration properly - extract return value if available
                if hasattr(ex, 'value') and ex.value is not None:
                    # If we got a value, return it as Ok
                    return self.return_(ex.value)
                elif hasattr(ex, 'value') and ex.value is None:
                    # If we got None value, this means we should use zero() 
                    result = self.zero()
                else:
                    # Default case - re-raise if no value
                    raise

            # If anything returns `None` (i.e raises StopIteration without a value) then
            # we expect the effect to have a zero method implemented.
            # But we also need to check if we got StopIteration with no value
            if result is None:
                result = self.zero()

            return await self.run(result)

        return async_wrapper


