from collections.abc import Callable, Iterable, Generator
from typing import Any, TypeVar

from expression.collections import seq
from expression.core import Builder
import asyncio


_TSource = TypeVar("_TSource")
_TResult = TypeVar("_TResult")


class SeqBuilder(Builder[_TSource, Iterable[Any]]):
    def bind(self, xs: Iterable[_TSource], fn: Callable[[_TSource], Iterable[_TResult]]) -> Iterable[_TResult]:
        result = []
        for x in xs:
            # Make sure we process all items correctly
            items = list(fn(x))
            result.extend(items)
        return result if result else seq.empty

    def return_(self, x: _TSource) -> Iterable[_TSource]:
        return seq.singleton(x)

    def return_from(self, xs: Iterable[_TSource]) -> Iterable[_TSource]:
        return xs

    def combine(self, xs: Iterable[_TSource], ys: Iterable[_TSource]) -> Iterable[_TSource]:
        ret = seq.concat(xs, ys)
        return ret

    def zero(self) -> Iterable[_TSource]:
        return seq.empty

    def __call__(
        self,  # Ignored self parameter
        fn: Callable[
            ...,  # Use ... instead of ParamSpec to avoid import issues
            Generator[_TSource | None, _TSource, _TSource | None] | Generator[_TSource | None, None, _TSource | None],
        ],
    ) -> Callable[..., Iterable[_TSource]]:
        """Sync seq builder."""
        def wrapper(*args, **kwargs):
            gen = fn(*args, **kwargs)
            done: list[bool] = []
            result: Iterable[_TSource] | None = None

            def binder(value: Any) -> Iterable[_TSource]:
                ret = self._send(gen, done, value)
                return ret

            try:
                result = self._send(gen, done)

                while not done[0] if done else False:
                    cont = self.bind(result, binder)

                    # Combine every result except the first
                    if result is None:
                        result = cont
                    else:
                        result = self.combine(result, cont)
            except StopIteration:
                pass

            # If anything returns `None` (i.e raises StopIteration without a value) then
            # we expect the effect to have a zero method implemented.
            if result is None:
                result = self.zero()

            return result

        return wrapper

    def _send(
        self,
        gen: Generator[Any, Any, Any],
        done: list[bool],
        value: _TSource | None = None,
    ) -> Iterable[_TSource]:
        """Handle sending values to generators, with special handling for async generators."""
        try:
            yielded = gen.send(value)
            # Check if the yielded value is awaitable (like Result or Option)
            if hasattr(yielded, '__await__') and not isinstance(yielded, type(gen)):
                # Handle awaitable values (like Result or Option) - this is tricky in sync context
                # For now, we'll treat them as regular values
                return self.return_(yielded)
            else:
                return self.return_(yielded)
        except AttributeError as ex:
            error_msg = str(ex)
            # Check if this is specifically an async generator error
            if ("object is not an iterator" in error_msg or 
                "'async_generator' object is not an iterator" in error_msg or
                "'async_generator' object has no attribute 'send'" in error_msg):
                # This is an async generator, but we're in a sync context, so we can't use __anext__
                # Just fall through to default behavior - let the caller handle this appropriately
                try:
                    yielded = next(gen)
                    return self.return_(yielded)
                except StopIteration as stop_ex:
                    done.append(True)
                    # Return of a value in the generator produces StopIteration with a value
                    if stop_ex.value is not None:
                        return self.return_(stop_ex.value)
                    raise
            elif "'object' object has no attribute 'send'" in error_msg or "has no attribute 'send'" in error_msg:
                # Handle iterators that don't support send (like list_iterator)
                try:
                    yielded = next(gen)
                    return self.return_(yielded)
                except StopIteration as stop_ex:
                    done.append(True)
                    # Return of a value in the generator produces StopIteration with a value
                    if stop_ex.value is not None:
